insert into jj_collect.catalog(id,data) values('nu-151','{"id": "nu-151", "number": 151, "name_es": "Un pliegue de cariño", "name_en": "A Fold of Care", "character": "duo", "theme": "cotidiano", "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Si cada intento queda distinto, tendremos más de una razón para probar juntos.", "dedication_en": "If every attempt turns out differently, we will have more than one reason to try together.", "art": 0, "collection": "sexto-universo"}'::jsonb) on conflict(id) do nothing;
