insert into jj_collect.catalog(id,data) values('nu-172','{"id": "nu-172", "number": 172, "name_es": "La voz de los cometas", "name_en": "The Voice of Comets", "character": "julisa", "theme": "fantasia", "rarity": 2, "sell": 80, "scrap": 12, "craft": 70, "dedication_es": "No necesitas un escenario enorme para que lo que compartes conmigo me importe.", "dedication_en": "You do not need a grand stage for what you share with me to matter.", "art": 21, "collection": "sexto-universo"}'::jsonb) on conflict(id) do nothing;
